                swift: "struct Zoom {\n    iterate: Shader,\n    present: Shader,\n    compute: Pass,\n    passes: Vec<Pass>,\n    reference: Reference,\n    motion: Mutex<Motion>,\n}\n\n/// Where the zoom is, in doublings from the first view, and how the pointer last moved.\nstruct Motion {\n    zoom: f64,\n    direction: f64,\n    last: Option<f64>,\n    pointer: Option<Array(repeating: f32, count: 2)>,\n    moved: f64,\n}\n\nimpl Zoom {\n    fn new() -> Result<Self, Failure> {\n        let header = format!(\"const ORBIT: u32 = {ORBIT}u;\\nconst PIXELS: u32 = {PIXELS}u;\")\n\n        let iterate = try Shader([header.asStr(), ITERATE])\n        try iterate.set(\"view.budget\", 1000)\n\n        // The library brings the palette that present.wgsl calls.\n        let present = try Shader([\"gradient/palette_iq\", header.asStr(), PRESENT])\n        try present.set(\"look.density\", 0.02)\n        try present.set(\"look.phase\", 0.6)\n        try present.set(\"look.inside_color\", [0.02, 0.02, 0.05])\n\n        // One orbit at the precision the deepest view needs, sent to the GPU once.\n        let reference = Reference(TARGET, DEPTH)\n        try iterate.set(\"orbit\", bytemuck.castSlice.<f32, u8>(reference.orbit))\n\n        let compute = Pass.fromShader(\"iterate\", iterate)\n        let draw = Pass.fromShader(\"present\", present)\n        Ok(Zoom {\n            passes: [compute.clone(), draw],\n            iterate,\n            present,\n            compute,\n            reference,\n            motion: Mutex.new(Motion {\n                zoom: 0.0,\n                direction: 1.0,\n                last: nil,\n                pointer: nil,\n                moved: f64.NEGINFINITY,\n            }),\n        })\n    }",
                kotlin: "struct Zoom {\n    iterate: Shader,\n    present: Shader,\n    compute: Pass,\n    passes: Vec<Pass>,\n    reference: Reference,\n    motion: Mutex<Motion>,\n}\n\n/// Where the zoom is, in doublings from the first view, and how the pointer last moved.\nstruct Motion {\n    zoom: f64,\n    direction: f64,\n    last: Option<f64>,\n    pointer: Option<ByteArray(2)>,\n    moved: f64,\n}\n\nimpl Zoom {\n    fn new() -> Result<Self, Failure> {\n        val header = format!(\"const ORBIT: u32 = {ORBIT}u;\\nconst PIXELS: u32 = {PIXELS}u;\")\n\n        val iterate = Shader(listOf(header.asStr(), ITERATE))\n        iterate.set(\"view.budget\", 1000)\n\n        // The library brings the palette that present.wgsl calls.\n        val present = Shader(listOf(\"gradient/palette_iq\", header.asStr(), PRESENT))\n        present.set(\"look.density\", 0.02f)\n        present.set(\"look.phase\", 0.6f)\n        present.set(\"look.inside_color\", listOf(0.02f, 0.02f, 0.05f))\n\n        // One orbit at the precision the deepest view needs, sent to the GPU once.\n        val reference = Reference(TARGET, DEPTH)\n        iterate.set(\"orbit\", bytemuck.castSlice.<f32, u8>(reference.orbit))\n\n        val compute = Pass.fromShader(\"iterate\", iterate)\n        val draw = Pass.fromShader(\"present\", present)\n        Ok(Zoom { passes: arrayOf(compute.clone(), draw), iterate, present, compute, reference, motion: Mutex(Motion { zoom: 0.0, direction: 1.0, last: null, pointer: null, moved: f64.NEGINFINITY, }), })\n    }",
